"""Independent saved-only source checks for C111304 original actor histories.

No legal conclusion or physical camera claim is made from a CPU fixture.
"""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path
from typing import Mapping


def audit_history(path: Path, expected_sha256: str, expected_case_id: str,
                  expected_site_sha256: str, expected_frames: int = 900) -> dict:
    source = path.read_bytes()
    actual_sha256 = hashlib.sha256(source).hexdigest()
    if actual_sha256 != expected_sha256:
        raise ValueError('original history hash mismatch')
    try:
        rows = [json.loads(line) for line in source.decode('utf-8').splitlines() if line]
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('original history decode failed') from exc
    if len(rows) != expected_frames:
        raise ValueError('original history frame count mismatch')
    first = rows[0].get('original_frame')
    if type(first) is not int:
        raise ValueError('original frame identity missing')
    fixed = ('ego_id', 'crossing_vehicle_id', 'occupant_id', 'property_id',
             'ego_blueprint', 'crossing_blueprint', 'property_blueprint',
             'map_sha256', 'public_access_basis', 'site_sha256', 'camera_plan_sha256')
    baseline = {key: rows[0].get(key) for key in fixed}
    if any(not value for value in baseline.values()):
        raise ValueError('original fixed source missing')
    if baseline['site_sha256'] != expected_site_sha256:
        raise ValueError('site source mismatch')
    for offset, row in enumerate(rows):
        if row.get('case_id') != expected_case_id or row.get('original_frame') != first + offset:
            raise ValueError('case or original frame join mismatch')
        if any(row.get(key) != value for key, value in baseline.items()):
            raise ValueError('fixed source changed within recording')
        if row.get('occupant_vehicle_id') != baseline['crossing_vehicle_id']:
            raise ValueError('occupancy join mismatch')
        if not row.get('source_sha256') or not row.get('control_command_source_sha256'):
            raise ValueError('original control source missing')
    return {'case_id': expected_case_id, 'original_history_sha256': actual_sha256,
            'site_sha256': baseline['site_sha256'], 'map_sha256': baseline['map_sha256'],
            'first_original_frame': first, 'last_original_frame': first + expected_frames - 1,
            'frame_count': expected_frames, 'fixed': baseline,
            'physical_visibility_verified': False, 'legal_judgment': None}


def audit_comparison(left: Mapping, right: Mapping, difference: str) -> dict:
    if left.get('frame_count') != 900 or right.get('frame_count') != 900:
        raise ValueError('comparison original history incomplete')
    if not left.get('original_history_sha256') or not right.get('original_history_sha256'):
        raise ValueError('comparison source hash missing')
    fixed = ('map_sha256', 'site_sha256', 'public_access_basis',
             'ego_blueprint', 'crossing_blueprint', 'property_blueprint',
             'camera_plan_sha256')
    for key in fixed:
        if key not in left or key not in right or left[key] != right[key]:
            raise ValueError(f'comparison fixed source changed: {key}')
    if difference not in left or difference not in right or left[difference] == right[difference]:
        raise ValueError('comparison deliberate difference missing')
    if left.get('case_id') == right.get('case_id'):
        raise ValueError('comparison duplicates case')
    return {'left_case_id': left['case_id'], 'right_case_id': right['case_id'],
            'difference': difference, 'source_hashes': [left['original_history_sha256'],
                                                         right['original_history_sha256']],
            'legal_judgment': None}


def audit_native_acquisition(attempt: Path, receipt: Mapping) -> dict:
    """Rejoin sealed original source packets, actor rows and camera readbacks."""
    from encounter import CASES
    from native_acquisition import ASSIGNMENT

    expected_case = next((case for case in CASES
                          if receipt.get('case_id') == f'{ASSIGNMENT}__{case.case_id}'), None)
    if expected_case is None:
        raise ValueError('native receipt exact case unknown')
    for key, value in (('ego_target_speed_mps', expected_case.ego_speed_mps),
                       ('crossing_target_speed_mps', expected_case.crossing_speed_mps),
                       ('crossing_release_s', expected_case.crossing_release_s)):
        if receipt.get(key) != value:
            raise ValueError(f'native receipt {key} differs from exact case')
    expected = ('original-history.jsonl', 'original-packets.jsonl', 'original-cameras.jsonl',
                'trace.jsonl', 'video_frames.jsonl')
    keys = ('original_history_sha256', 'original_packets_sha256', 'original_cameras_sha256',
            'original_trace_sha256', 'original_frame_map_sha256')
    tables = []
    for name, key in zip(expected, keys):
        path = attempt / name
        if not path.is_file() or path.is_symlink():
            raise ValueError(f'{name} missing or redirected')
        raw = path.read_bytes()
        if hashlib.sha256(raw).hexdigest() != receipt.get(key):
            raise ValueError(f'{name} hash mismatch')
        try:
            tables.append([json.loads(line) for line in raw.decode('utf-8').splitlines() if line])
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ValueError(f'{name} decode failed') from exc
    histories, packets, cameras, traces, frame_maps = tables
    count = receipt.get('frame_count')
    if count != 900 or any(len(table) != count for table in tables):
        raise ValueError('original acquisition frame count mismatch')
    first = receipt.get('first_original_frame')
    if type(first) is not int or receipt.get('last_original_frame') != first + count - 1:
        raise ValueError('original acquisition frame range mismatch')
    for offset, (row, packet, camera) in enumerate(zip(histories, packets, cameras)):
        frame = first + offset
        if any(item.get('original_frame') != frame for item in (row, packet, camera)):
            raise ValueError('original acquisition frame join mismatch')
        source = json.dumps(packet, sort_keys=True, separators=(',', ':'), allow_nan=False).encode()
        if row.get('source_sha256') != hashlib.sha256(source).hexdigest():
            raise ValueError('actor source packet mismatch')
        controls = packet.get('control')
        if not isinstance(controls, dict):
            raise ValueError('control source packet missing')
        for key in ('ego_target_speed_mps', 'crossing_target_speed_mps', 'crossing_release_s'):
            if controls.get(key) != receipt[key]:
                raise ValueError(f'original {key} control differs from exact case')
        control_source = json.dumps(controls, sort_keys=True, separators=(',', ':'), allow_nan=False).encode()
        if row.get('control_command_source_sha256') != hashlib.sha256(control_source).hexdigest():
            raise ValueError('control source packet mismatch')
        for role, key in (('ego', 'ego_id'), ('crossing_vehicle', 'crossing_vehicle_id'),
                          ('occupant', 'occupant_id'), ('property', 'property_id')):
            actor = packet.get('actors', {}).get(role, {})
            if str(actor.get('id')) != row.get(key):
                raise ValueError(f'{role} original actor join mismatch')
            if role in ('ego', 'occupant', 'property') and actor.get('xy') != row.get(role + '_xy'):
                raise ValueError(f'{role} original position join mismatch')
            if role in ('ego', 'crossing_vehicle') and actor.get('speed_mps') != row.get('ego_speed_mps' if role == 'ego' else 'crossing_speed_mps'):
                raise ValueError(f'{role} original speed join mismatch')
            if role in ('ego', 'crossing_vehicle', 'property') and actor.get('blueprint') != row.get('crossing_blueprint' if role == 'crossing_vehicle' else role + '_blueprint'):
                raise ValueError(f'{role} original blueprint join mismatch')
        if str(packet['actors']['occupant'].get('vehicle_id')) != row.get('occupant_vehicle_id'):
            raise ValueError('occupant original vehicle join mismatch')
        if row.get('map_sha256') != receipt.get('map_sha256') or row.get('camera_plan_sha256') != receipt.get('camera_plan_sha256'):
            raise ValueError('map or camera plan source mismatch')
        if abs(row.get('elapsed_seconds', float('nan')) - histories[0].get('elapsed_seconds', float('nan')) - offset / 20) > 0.001:
            raise ValueError('original elapsed-time join mismatch')
        camera_hashes = camera.get('camera_sha256')
        if not isinstance(camera_hashes, dict) or set(camera_hashes) != {'front', 'rear', 'left', 'right'} or not all(isinstance(h, str) and len(h) == 64 for h in camera_hashes.values()):
            raise ValueError('four original camera hashes missing')
        if row.get('case_id') != receipt.get('case_id') or row.get('site_sha256') != receipt.get('site_sha256'):
            raise ValueError('case or site source mismatch')
        ego = packet['actors']['ego']
        elapsed = row['elapsed_seconds'] - histories[0]['elapsed_seconds']
        if traces[offset] != {
                'frame': frame, 'time_s': elapsed,
                'position_m': list(ego['xy']),
                'position': {'x': ego['xy'][0], 'y': ego['xy'][1], 'z': ego.get('z')},
                'heading_deg': ego.get('heading_deg'), 'speed_mps': ego['speed_mps']}:
            raise ValueError('original trace source join mismatch')
        if frame_maps[offset] != {'video_frame': offset, 'carla_frame': frame, 'time_s': elapsed}:
            raise ValueError('original frame map source join mismatch')
    return {'case_id': receipt['case_id'], 'frame_count': count,
            'original_history_sha256': receipt['original_history_sha256'],
            'original_cameras_sha256': receipt['original_cameras_sha256'],
            'full_video_decode': False, 'actual_pixels': False,
            'physical_completion': False, 'legal_judgment': None}


def finalize_saved_measurements(attempt: Path, case) -> dict:
    """Measure original packets only after independent sealed-source rejoin."""
    from encounter import CASES, measure_history
    from native_acquisition import ASSIGNMENT

    if case not in CASES:
        raise ValueError('unknown exact case')
    receipt_path = attempt / 'native-receipt.json'
    if not receipt_path.is_file() or receipt_path.is_symlink():
        raise ValueError('native receipt missing or redirected')
    try:
        receipt = json.loads(receipt_path.read_text(encoding='utf-8'))
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError('native receipt decode failed') from exc
    if (receipt.get('assignment_id') != ASSIGNMENT or
            receipt.get('case_id') != f'{ASSIGNMENT}__{case.case_id}'):
        raise ValueError('native receipt exact case mismatch')
    source = audit_native_acquisition(attempt, receipt)
    rows = [json.loads(line) for line in (attempt / 'original-history.jsonl').read_text(
        encoding='utf-8').splitlines() if line]
    measured = measure_history(rows, case)
    if measured['frame_count'] != source['frame_count']:
        raise ValueError('measurement source count mismatch')
    return {'assignment_id': ASSIGNMENT, 'case_id': receipt['case_id'],
            'original_history_sha256': source['original_history_sha256'],
            'native_receipt_sha256': hashlib.sha256(receipt_path.read_bytes()).hexdigest(),
            'source_audit': source, 'measurements': measured,
            'actual_pixels': False, 'physical_completion': False, 'legal_judgment': None}


def audit_saved_timing_pair(left_attempt: Path, right_attempt: Path,
                            comparison_id: str) -> dict:
    """Reopen both original attempts before a declared timing comparison.

    Distances describe physical trajectories only. They cannot establish a
    willful or wanton state or a statutory spacing threshold.
    """
    from encounter import CASES

    pairs = {
        'highway_person_north_timing': ('person_north_early', 'person_north_late'),
        'highway_person_south_timing': ('person_south_early', 'person_south_late'),
        'premises_person_timing': ('premises_person_early', 'premises_person_late'),
    }
    if comparison_id not in pairs:
        raise ValueError('unsupported exact timing comparison')
    by_id = {case.case_id: case for case in CASES}
    early_id, late_id = pairs[comparison_id]
    early = finalize_saved_measurements(left_attempt, by_id[early_id])
    late = finalize_saved_measurements(right_attempt, by_id[late_id])
    first = json.loads((left_attempt / 'native-receipt.json').read_text(encoding='utf-8'))
    second = json.loads((right_attempt / 'native-receipt.json').read_text(encoding='utf-8'))
    fixed = ('site_sha256', 'map_sha256', 'camera_plan_sha256',
             'public_access_basis', 'ego_target_speed_mps',
             'crossing_target_speed_mps', 'frame_count', 'original_fps')
    for key in fixed:
        if first.get(key) != second.get(key):
            raise ValueError(f'comparison fixed condition changed: {key}')
    # The actor blueprints are in the sealed original histories, not receipts.
    with (left_attempt / 'original-history.jsonl').open(encoding='utf-8') as source:
        first_row = json.loads(source.readline())
    with (right_attempt / 'original-history.jsonl').open(encoding='utf-8') as source:
        second_row = json.loads(source.readline())
    for key in ('ego_blueprint', 'crossing_blueprint', 'property_blueprint'):
        if first_row.get(key) != second_row.get(key):
            raise ValueError(f'comparison fixed condition changed: {key}')
    if first['crossing_release_s'] >= second['crossing_release_s']:
        raise ValueError('comparison release order missing')
    a = early['measurements']['min_ego_occupant_center_distance_m']
    b = late['measurements']['min_ego_occupant_center_distance_m']
    if abs(a - b) <= 1e-6:
        raise ValueError('comparison measured encounter difference missing')
    return {'comparison_id': comparison_id,
            'case_ids': [early['case_id'], late['case_id']],
            'original_history_sha256': [early['original_history_sha256'],
                                        late['original_history_sha256']],
            'native_receipt_sha256': [early['native_receipt_sha256'],
                                      late['native_receipt_sha256']],
            'crossing_release_s': [first['crossing_release_s'], second['crossing_release_s']],
            'min_ego_occupant_center_distance_m': [a, b],
            'actual_pixels': False, 'physical_completion': False,
            'legal_judgment': None}


def audit_saved_property_pair(near_attempt: Path, far_attempt: Path) -> dict:
    """Reopen both sealed captures for the declared property-position pair.

    This compares measured center distances, without inferring damage, risk,
    visibility, or the driver's state of mind from position alone.
    """
    from encounter import CASES

    by_id = {case.case_id: case for case in CASES}
    near = finalize_saved_measurements(near_attempt, by_id['property_near'])
    far = finalize_saved_measurements(far_attempt, by_id['property_far'])
    receipts = [json.loads((path / 'native-receipt.json').read_text(encoding='utf-8'))
                for path in (near_attempt, far_attempt)]
    fixed_receipt = ('site_sha256', 'map_sha256', 'camera_plan_sha256',
                     'public_access_basis', 'ego_target_speed_mps',
                     'crossing_target_speed_mps', 'crossing_release_s',
                     'frame_count', 'original_fps')
    for key in fixed_receipt:
        if receipts[0].get(key) != receipts[1].get(key):
            raise ValueError(f'comparison fixed condition changed: {key}')
    first_rows = []
    for path in (near_attempt, far_attempt):
        with (path / 'original-history.jsonl').open(encoding='utf-8') as source:
            first_rows.append(json.loads(source.readline()))
    fixed_actor = ('ego_blueprint', 'crossing_blueprint', 'property_blueprint',
                   'ego_id', 'crossing_vehicle_id', 'occupant_id',
                   'occupant_vehicle_id', 'ego_xy', 'occupant_xy')
    for key in fixed_actor:
        if first_rows[0].get(key) != first_rows[1].get(key):
            raise ValueError(f'comparison fixed condition changed: {key}')
    if first_rows[0].get('property_xy') == first_rows[1].get('property_xy'):
        raise ValueError('comparison property position difference missing')
    a = near['measurements']['min_ego_property_center_distance_m']
    b = far['measurements']['min_ego_property_center_distance_m']
    if not a < b:
        raise ValueError('comparison measured near/far property order missing')
    return {'comparison_id': 'highway_property_position',
            'case_ids': [near['case_id'], far['case_id']],
            'original_history_sha256': [near['original_history_sha256'],
                                        far['original_history_sha256']],
            'native_receipt_sha256': [near['native_receipt_sha256'],
                                      far['native_receipt_sha256']],
            'first_property_xy': [first_rows[0]['property_xy'],
                                  first_rows[1]['property_xy']],
            'min_ego_property_center_distance_m': [a, b],
            'actual_pixels': False, 'physical_completion': False,
            'legal_judgment': None}


def audit_saved_approach_pair(north_attempt: Path, south_attempt: Path) -> dict:
    """Reopen sealed highway attempts and compare observed ego approach vectors.

    Opposite motion is a measured contrast only. It does not establish that
    either maneuver was physically safe or legally willful or wanton.
    """
    from encounter import CASES

    by_id = {case.case_id: case for case in CASES}
    north = finalize_saved_measurements(north_attempt, by_id['person_north_early'])
    south = finalize_saved_measurements(south_attempt, by_id['person_south_early'])
    receipts = [json.loads((path / 'native-receipt.json').read_text(encoding='utf-8'))
                for path in (north_attempt, south_attempt)]
    fixed_receipt = ('site_sha256', 'map_sha256', 'camera_plan_sha256',
                     'public_access_basis', 'ego_target_speed_mps',
                     'crossing_target_speed_mps', 'crossing_release_s',
                     'frame_count', 'original_fps')
    for key in fixed_receipt:
        if receipts[0].get(key) != receipts[1].get(key):
            raise ValueError(f'comparison fixed condition changed: {key}')
    if receipts[0].get('public_access_basis') != 'highway':
        raise ValueError('approach comparison requires sourced highway context')
    endpoints = []
    for path in (north_attempt, south_attempt):
        with (path / 'original-history.jsonl').open(encoding='utf-8') as source:
            rows = [json.loads(line) for line in source]
        endpoints.append((rows[0], rows[-1]))
    fixed_actor = ('ego_blueprint', 'crossing_blueprint', 'property_blueprint',
                   'ego_id', 'crossing_vehicle_id', 'occupant_id',
                   'occupant_vehicle_id', 'property_id', 'occupant_xy', 'property_xy')
    for key in fixed_actor:
        if endpoints[0][0].get(key) != endpoints[1][0].get(key):
            raise ValueError(f'comparison fixed condition changed: {key}')
    vectors = []
    for first, last in endpoints:
        a, b = first['ego_xy'], last['ego_xy']
        vector = (b[0] - a[0], b[1] - a[1])
        length = math.hypot(*vector)
        if length <= 1.0:
            raise ValueError('comparison original ego approach motion missing')
        vectors.append((vector, length))
    cosine = sum(a * b for a, b in zip(vectors[0][0], vectors[1][0])) / (
        vectors[0][1] * vectors[1][1])
    if cosine >= -0.5:
        raise ValueError('comparison observed approach directions not opposed')
    return {'comparison_id': 'highway_person_approach_direction',
            'case_ids': [north['case_id'], south['case_id']],
            'original_history_sha256': [north['original_history_sha256'],
                                        south['original_history_sha256']],
            'native_receipt_sha256': [north['native_receipt_sha256'],
                                      south['native_receipt_sha256']],
            'ego_displacement_xy_m': [list(vectors[0][0]), list(vectors[1][0])],
            'direction_cosine': cosine, 'actual_pixels': False,
            'physical_completion': False, 'legal_judgment': None}

"""Independent saved-camera integrity and decode audit for C111304.

The camera plan and media inventory are local operator inputs. A CPU fixture can
prove the decoder path, but cannot prove that a person or property is visible.
"""
from __future__ import annotations

import hashlib
import json
from fractions import Fraction
from pathlib import Path
import subprocess

CAMERAS = ('front', 'rear', 'left', 'right')
CASE_PREFIX = 'testing__C111304__NRS-484B-653-1a__motor_vehicle_driver__'


def _digest(path: Path) -> str:
    h = hashlib.sha256()
    with path.open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest()


def _run(command: list[str]) -> subprocess.CompletedProcess:
    result = subprocess.run(command, capture_output=True, text=True, timeout=120)
    if result.returncode:
        raise ValueError(f'media tool failed: {command[0]}: {result.stderr[-400:]}')
    return result


def audit_media(attempt: Path, receipt: dict, inventory: dict, camera_plan: dict,
                *, allow_diagnostic: bool = False) -> dict:
    """Verify four attempt-confined encoded streams, then fully decode each.

    The inventory binds exact encoded-file hashes to the sealed Native receipt.
    Frame readback hashes in original-cameras.jsonl remain separate evidence;
    encoded pixels are not assumed byte-identical to original sensor packets.
    """
    from encounter import CASES

    allowed = {CASE_PREFIX + case.case_id for case in CASES}
    case_id = receipt.get('case_id')
    if case_id not in allowed or inventory.get('case_id') != case_id:
        raise ValueError('exact case identity mismatch')
    if inventory.get('source_kind') != 'original_encoded' and not (
        allow_diagnostic and inventory.get('source_kind') == 'synthetic_fixture'
    ):
        raise ValueError('original encoded camera source required')
    if receipt.get('frame_count') != 900 or receipt.get('original_fps') != 20:
        raise ValueError('original acquisition duration or cadence mismatch')
    sealed_path = attempt / 'native-receipt.json'
    if not sealed_path.is_file() or sealed_path.is_symlink():
        raise ValueError('native receipt missing or redirected')
    if inventory.get('native_receipt_sha256') != _digest(sealed_path):
        raise ValueError('native receipt source hash mismatch')
    try:
        sealed = json.loads(sealed_path.read_text(encoding='utf-8'))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError('native receipt decode failed') from exc
    if sealed != receipt:
        raise ValueError('native receipt content mismatch')
    plan_source = json.dumps(camera_plan, sort_keys=True, separators=(',', ':'), allow_nan=False).encode()
    if hashlib.sha256(plan_source).hexdigest() != receipt.get('camera_plan_sha256'):
        raise ValueError('camera plan source hash mismatch')
    if set(inventory.get('cameras', {})) != set(CAMERAS) or set(camera_plan.get('cameras', {})) != set(CAMERAS):
        raise ValueError('four camera entries required')
    decoded = {}
    used = set()
    for camera in CAMERAS:
        item = inventory['cameras'][camera]
        name = item.get('path')
        if not isinstance(name, str) or not name or Path(name).is_absolute():
            raise ValueError('camera media path invalid')
        candidate = attempt / name
        path = candidate.resolve()
        if (attempt.resolve() not in path.parents or not path.is_file() or
                candidate.is_symlink() or path in used):
            raise ValueError('camera media missing, redirected or reused')
        used.add(path)
        if _digest(path) != item.get('sha256'):
            raise ValueError(f'{camera} encoded media hash mismatch')
        probed = _run(['ffprobe', '-v', 'error', '-select_streams', 'v:0',
                       '-count_frames', '-show_entries',
                       'stream=width,height,avg_frame_rate,nb_read_frames',
                       '-of', 'json', str(path)])
        streams = json.loads(probed.stdout).get('streams', [])
        if len(streams) != 1:
            raise ValueError(f'{camera} video stream missing')
        stream = streams[0]
        expected = camera_plan['cameras'][camera]
        if (stream.get('width'), stream.get('height')) != (expected.get('width'), expected.get('height')):
            raise ValueError(f'{camera} dimensions differ from camera plan')
        try:
            fps = Fraction(stream['avg_frame_rate'])
            frames = int(stream['nb_read_frames'])
        except (KeyError, ValueError, ZeroDivisionError) as exc:
            raise ValueError(f'{camera} frame metadata missing') from exc
        if fps != 20 or frames != 900:
            raise ValueError(f'{camera} frame count or cadence mismatch')
        _run(['ffmpeg', '-v', 'error', '-xerror', '-i', str(path), '-map', '0:v:0',
              '-f', 'null', '-'])
        decoded[camera] = {'encoded_sha256': item['sha256'], 'frames': frames,
                           'fps': 20, 'width': stream['width'], 'height': stream['height'],
                           'full_decode': True}
    return {'case_id': case_id, 'native_receipt_sha256': inventory['native_receipt_sha256'],
            'camera_plan_sha256': receipt['camera_plan_sha256'], 'cameras': decoded,
            'source_kind': inventory['source_kind'],
            'actual_body_visibility': False, 'physical_completion': False,
            'legal_judgment': None}

"""Lazy CARLA binding for a reviewed C111304 intersection source packet.

The packet must contain numeric original map poses and actor blueprints. This
module does not infer highway status, occupancy, or legal state from map names.
"""
from __future__ import annotations

from copy import deepcopy
import io
import math
import threading
from pathlib import Path

from PIL import Image

from native_acquisition import CAMERAS


def _number(value, label):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError(label + ' finite source required')
    return float(value)


def _pose(carla, value):
    if not isinstance(value, dict):
        raise ValueError('reviewed transform missing')
    return carla.Transform(
        carla.Location(x=_number(value.get('x'), 'x'),
                       y=_number(value.get('y'), 'y'),
                       z=_number(value.get('z'), 'z')),
        carla.Rotation(yaw=_number(value.get('yaw'), 'yaw'),
                       pitch=_number(value.get('pitch', 0), 'pitch'),
                       roll=_number(value.get('roll', 0), 'roll')))


class CarlaEncounterAdapter:
    """Own both vehicles, visible occupant/property actors and four cameras."""

    def __init__(self, world, carla, site, camera_plan):
        self.world, self.carla, self.site = world, carla, site
        self.camera_plan = camera_plan
        self.owned = []
        self.cameras = {}
        self.images = {name: {} for name in CAMERAS}
        self.condition = threading.Condition()
        self.callback_error = None
        self.original_settings = None
        self.routes = {}
        self.current_frame = None
        self.current_elapsed = None
        self.start_elapsed = None
        self.commands = {}
        self.occupant_vehicle_id = None
        self.occupant_id = None
        self.camera_output = None

    def start(self):
        cameras = self.camera_plan.get('cameras')
        if not isinstance(cameras, dict) or set(cameras) != set(CAMERAS):
            raise ValueError('four reviewed camera sources required')
        for name in CAMERAS:
            row = cameras[name]
            if not isinstance(row, dict) or row.get('blueprint_id') != 'sensor.camera.rgb':
                raise ValueError(name + ' reviewed RGB camera source required')
            if type(row.get('width')) is not int or type(row.get('height')) is not int or min(row['width'], row['height']) < 1:
                raise ValueError(name + ' camera dimensions missing')
            _pose(self.carla, row.get('transform'))
        self.original_settings = deepcopy(self.world.get_settings())
        settings = self.world.get_settings()
        settings.synchronous_mode = True
        settings.fixed_delta_seconds = 0.05
        self.world.apply_settings(settings)
        readback = self.world.get_settings()
        if not readback.synchronous_mode or readback.fixed_delta_seconds != 0.05:
            self.cleanup()
            raise ValueError('20 Hz synchronous world readback failed')

    def _spawn(self, blueprint_id, transform, *, attach_to=None, attributes=None):
        if not isinstance(blueprint_id, str) or not blueprint_id:
            raise ValueError('reviewed actor blueprint missing')
        blueprint = self.world.get_blueprint_library().find(blueprint_id)
        for key, value in (attributes or {}).items():
            blueprint.set_attribute(key, str(value))
        pose = _pose(self.carla, transform)
        actor = (self.world.try_spawn_actor(blueprint, pose, attach_to=attach_to)
                 if attach_to is not None else self.world.try_spawn_actor(blueprint, pose))
        if actor is None:
            raise ValueError('reviewed actor spawn failed: ' + blueprint_id)
        self.owned.append(actor)
        return actor

    def spawn_vehicle(self, waypoint, role):
        if role not in ('ego', 'crossing') or not isinstance(waypoint, dict):
            raise ValueError('reviewed lane waypoint missing')
        if not waypoint.get('source_sha256'):
            raise ValueError('lane waypoint source hash missing')
        blueprints = self.site.get('actor_blueprints', {})
        return self._spawn(blueprints.get(role), waypoint.get('transform'))

    def register_occupant(self, vehicle, descriptor):
        if not isinstance(descriptor, dict) or not descriptor.get('source_sha256'):
            raise ValueError('reviewed occupant source missing')
        actor = self._spawn(descriptor.get('blueprint_id'), descriptor.get('relative_transform'), attach_to=vehicle)
        self.occupant_vehicle_id = str(vehicle.id)
        self.occupant_id = actor.id
        return actor

    def spawn_property(self, anchor, offset_m):
        if not isinstance(anchor, dict) or not anchor.get('source_sha256'):
            raise ValueError('reviewed property anchor missing')
        transform = deepcopy(anchor.get('transform'))
        axis = anchor.get('offset_axis_xy')
        if not isinstance(transform, dict) or not isinstance(axis, list) or len(axis) != 2:
            raise ValueError('reviewed property offset axis missing')
        ux, uy = (_number(axis[0], 'property axis'), _number(axis[1], 'property axis'))
        if abs(math.hypot(ux, uy) - 1) > 0.001:
            raise ValueError('property offset axis must be unit length')
        transform['x'] = _number(transform.get('x'), 'property x') + _number(offset_m, 'property offset') * ux
        transform['y'] = _number(transform.get('y'), 'property y') + offset_m * uy
        return self._spawn(anchor.get('blueprint_id'), transform)

    def set_route(self, actor, route, *, target_speed_mps, release_s=0):
        if not isinstance(route, list) or len(route) < 2 or any(
            not isinstance(row, dict) or not row.get('source_sha256') or
            not isinstance(row.get('transform'), dict) for row in route
        ):
            raise ValueError('reviewed route geometry missing')
        speed = _number(target_speed_mps, 'target speed')
        release = _number(release_s, 'release time')
        if speed <= 0 or release < 0:
            raise ValueError('target speed or release time invalid')
        self.routes[actor.id] = {'actor': actor, 'route': route, 'index': 1,
                                 'target_speed_mps': speed, 'release_s': release}

    def start_cameras(self, ego, output: Path | None = None):
        if len(self.routes) != 2 or not self.original_settings:
            raise ValueError('vehicles and synchronous world required before cameras')
        if output is not None:
            if not output.is_dir() or (output / 'cameras').exists():
                raise ValueError('fresh original camera output required')
            self.camera_output = output
            for name in CAMERAS:
                (output / 'cameras' / name).mkdir(parents=True)
        try:
            for name in CAMERAS:
                spec = self.camera_plan['cameras'][name]
                sensor = self._spawn('sensor.camera.rgb', spec['transform'], attach_to=ego,
                                     attributes={'image_size_x': spec['width'],
                                                 'image_size_y': spec['height'],
                                                 'sensor_tick': '0.05'})
                self.cameras[name] = sensor
                sensor.listen(self._callback(name, spec))
        except BaseException:
            self.cleanup()
            raise

    def _callback(self, name, spec):
        def receive(image):
            try:
                if (image.width, image.height) != (spec['width'], spec['height']):
                    raise ValueError(name + ' camera dimensions changed')
                raw = bytes(image.raw_data)
                if len(raw) != image.width * image.height * 4:
                    raise ValueError(name + ' camera BGRA bytes missing')
                picture = Image.frombytes('RGBA', (image.width, image.height), raw,
                                          'raw', 'BGRA')
                stream = io.BytesIO()
                picture.save(stream, format='PNG')
                encoded = stream.getvalue()
                with self.condition:
                    if image.frame in self.images[name]:
                        raise ValueError(name + ' duplicate original camera frame')
                    self.images[name][image.frame] = encoded
                    self.condition.notify_all()
            except BaseException as exc:
                with self.condition:
                    self.callback_error = exc
                    self.condition.notify_all()
        return receive

    def _control(self, item, elapsed):
        actor = item['actor']
        transform = actor.get_transform()
        velocity = actor.get_velocity()
        speed = math.sqrt(velocity.x ** 2 + velocity.y ** 2 + velocity.z ** 2)
        route = item['route']
        index = item['index']
        target = route[index]['transform']
        dx = _number(target.get('x'), 'route x') - transform.location.x
        dy = _number(target.get('y'), 'route y') - transform.location.y
        if math.hypot(dx, dy) < 2 and index + 1 < len(route):
            index += 1
            item['index'] = index
            target = route[index]['transform']
            dx = _number(target.get('x'), 'route x') - transform.location.x
            dy = _number(target.get('y'), 'route y') - transform.location.y
        heading = math.degrees(math.atan2(dy, dx))
        error = (heading - transform.rotation.yaw + 180) % 360 - 180
        steer = max(-1.0, min(1.0, error / 35))
        active = elapsed >= item['release_s']
        throttle = max(0.0, min(0.6, (item['target_speed_mps'] - speed) * 0.25)) if active else 0.0
        brake = 1.0 if not active else (min(1.0, (speed - item['target_speed_mps']) * 0.25) if speed > item['target_speed_mps'] else 0.0)
        actor.apply_control(self.carla.VehicleControl(throttle=throttle, brake=brake, steer=steer))
        return {'target_speed_mps': item['target_speed_mps'], 'release_s': item['release_s'],
                'throttle': throttle, 'brake': brake, 'steer': steer}

    def tick(self):
        if len(self.cameras) != 4 or len(self.routes) != 2:
            raise ValueError('owned actors and cameras required')
        elapsed = (0.0 if self.current_elapsed is None else
                   self.current_elapsed - self.start_elapsed + 0.05)
        self.commands = {actor_id: self._control(item, elapsed) for actor_id, item in self.routes.items()}
        frame = self.world.tick()
        snapshot = self.world.get_snapshot()
        if snapshot.frame != frame:
            raise ValueError('world frame/snapshot mismatch')
        self.current_frame = frame
        self.current_elapsed = float(snapshot.timestamp.elapsed_seconds)
        if self.start_elapsed is None:
            self.start_elapsed = self.current_elapsed
        return frame, self.current_elapsed

    def read_actor(self, actor):
        if self.current_frame is None:
            raise ValueError('original frame missing')
        transform, velocity = actor.get_transform(), actor.get_velocity()
        result = {'original_frame': self.current_frame, 'id': actor.id,
                  'xy': [float(transform.location.x), float(transform.location.y)],
                  'z': float(transform.location.z),
                  'heading_deg': float(transform.rotation.yaw),
                  'speed_mps': math.sqrt(velocity.x ** 2 + velocity.y ** 2 + velocity.z ** 2),
                  'blueprint': actor.type_id}
        if actor.id == self.occupant_id:
            result['vehicle_id'] = self.occupant_vehicle_id
        return result

    def read_control(self, ego, crossing):
        if self.current_frame is None or ego.id not in self.commands or crossing.id not in self.commands:
            raise ValueError('original control readback missing')
        return {'original_frame': self.current_frame,
                'ego_target_speed_mps': self.commands[ego.id]['target_speed_mps'],
                'crossing_target_speed_mps': self.commands[crossing.id]['target_speed_mps'],
                'crossing_release_s': self.commands[crossing.id]['release_s'],
                'ego_command': self.commands[ego.id],
                'crossing_command': self.commands[crossing.id]}

    def read_camera(self, name):
        if name not in CAMERAS or self.current_frame is None:
            raise ValueError('original camera/frame missing')
        with self.condition:
            if not self.condition.wait_for(lambda: self.callback_error is not None or
                                           self.current_frame in self.images[name], timeout=5):
                raise ValueError(name + ' original camera callback timed out')
            if self.callback_error is not None:
                raise ValueError(name + ' original camera callback failed') from self.callback_error
            encoded = self.images[name].pop(self.current_frame)
            if self.camera_output is not None:
                path = self.camera_output / 'cameras' / name / f'{self.current_frame:06d}.png'
                if path.exists():
                    raise ValueError(name + ' original camera frame already exists')
                path.write_bytes(encoded)
            return self.current_frame, encoded

    def brake(self, ego):
        ego.apply_control(self.carla.VehicleControl(throttle=0.0, brake=1.0, steer=0.0))

    def destroy(self, actor):
        if actor in self.owned:
            if actor in self.cameras.values():
                actor.stop()
            actor.destroy()
            self.owned.remove(actor)

    def cleanup(self):
        for actor in reversed(tuple(self.owned)):
            self.destroy(actor)
        if self.original_settings is not None:
            self.world.apply_settings(self.original_settings)
            self.original_settings = None

"""Saved-only conversion of sealed original C111304 camera PNG frames."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path
import shutil
import subprocess

from native_acquisition import CAMERAS


def _sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _safe(path, attempt):
    root = attempt.resolve()
    if not path.is_file() or path.is_symlink() or root not in path.resolve().parents:
        raise ValueError('original camera source missing or redirected')
    parent = path.parent
    while parent != attempt:
        if parent.is_symlink():
            raise ValueError('original camera source missing or redirected')
        parent = parent.parent


def encode_original_cameras(attempt: Path, camera_plan: dict, *, ffmpeg='ffmpeg') -> dict:
    """Require every sealed PNG, then make four FFV1 streams and an inventory."""
    from media_audit import audit_media

    receipt_path = attempt / 'native-receipt.json'
    camera_rows_path = attempt / 'original-cameras.jsonl'
    _safe(receipt_path, attempt)
    _safe(camera_rows_path, attempt)
    receipt = json.loads(receipt_path.read_text(encoding='utf-8'))
    if receipt.get('frame_count') != 900 or receipt.get('original_fps') != 20:
        raise ValueError('sealed original timebase mismatch')
    if _sha(camera_rows_path) != receipt.get('original_cameras_sha256'):
        raise ValueError('sealed original camera trace hash mismatch')
    rows = [json.loads(line) for line in camera_rows_path.read_text(encoding='utf-8').splitlines()]
    start = receipt.get('first_original_frame')
    if type(start) is not int or len(rows) != 900:
        raise ValueError('900 original camera rows required')
    if set(camera_plan.get('cameras', {})) != set(CAMERAS):
        raise ValueError('four camera plan entries required')
    for index, row in enumerate(rows):
        frame = start + index
        if row.get('original_frame') != frame or set(row.get('camera_sha256', {})) != set(CAMERAS):
            raise ValueError('original camera frame or channel join mismatch')
        for name in CAMERAS:
            path = attempt / 'cameras' / name / f'{frame:06d}.png'
            _safe(path, attempt)
            if _sha(path) != row['camera_sha256'][name]:
                raise ValueError(name + ' original PNG hash mismatch')
    encoded_root = attempt / 'encoded'
    if encoded_root.exists():
        raise ValueError('encoded attempt output already exists')
    encoded_root.mkdir()
    cameras = {}
    for name in CAMERAS:
        source = attempt / 'cameras' / name / '%06d.png'
        output = encoded_root / (name + '.mkv')
        command = [ffmpeg, '-v', 'error', '-xerror', '-framerate', '20',
                   '-start_number', str(start), '-i', str(source),
                   '-frames:v', '900', '-c:v', 'ffv1', str(output)]
        result = subprocess.run(command, capture_output=True, text=True, timeout=300)
        if result.returncode or not output.is_file():
            raise ValueError(name + ' saved FFV1 conversion failed: ' + result.stderr[-300:])
        cameras[name] = {'path': str(output.relative_to(attempt)), 'sha256': _sha(output)}
    inventory = {'case_id': receipt['case_id'], 'source_kind': 'original_encoded',
                 'native_receipt_sha256': _sha(receipt_path), 'cameras': cameras}
    audit_media(attempt, receipt, inventory, camera_plan)
    for source_name, view_name in (('front', 'overview'), ('rear', 'approach'),
                                   ('left', 'reference_corner'), ('right', 'driver_reference')):
        view = attempt / (view_name + '.mkv')
        if view.exists():
            raise ValueError('saved four-view source already exists: ' + view_name)
        shutil.copy2(encoded_root / (source_name + '.mkv'), view)
    (attempt / 'camera-media-inventory.json').write_text(
        json.dumps(inventory, sort_keys=True, indent=2) + '\n', encoding='utf-8')
    return inventory


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--attempt', type=Path, required=True)
    parser.add_argument('--camera-plan', type=Path, required=True)
    args = parser.parse_args()
    if not args.camera_plan.is_file() or args.camera_plan.is_symlink():
        raise ValueError('reviewed camera plan missing or redirected')
    plan = json.loads(args.camera_plan.read_text(encoding='utf-8'))
    print(json.dumps(encode_original_cameras(args.attempt, plan), sort_keys=True))


if __name__ == '__main__':
    main()

